"""Validate builder-tool arguments against their offered JSON schema."""

from __future__ import annotations

import re
from collections.abc import Mapping
from typing import Any, Optional

from jsonschema import (
    Draft7Validator,
    Draft202012Validator,
    ValidationError,
)
from referencing import Registry

from rasa.agents.schemas.agent_tool_schema import AgentToolSchema
from rasa.mantle.orchestration.tool_execution.payload import (
    INVALID_ARGUMENTS_ERROR_CODE,
    format_retryable_error_as_json,
)


def validate_tool_arguments(
    schema: Optional[AgentToolSchema],
    arguments: Mapping[str, Any],
) -> Optional[str]:
    """Return a retryable error when arguments violate the offered schema."""
    if schema is None or not schema.parameters:
        return None

    try:
        return _validate_parameters(schema.parameters, arguments)
    except Exception:
        return unusable_tool_schema_error()


def unusable_tool_schema_error() -> str:
    """Return a recoverable failure for an unusable offered schema."""
    return format_retryable_error_as_json(
        "The tool argument schema is invalid; the tool was not executed.",
        code=INVALID_ARGUMENTS_ERROR_CODE,
    )


def _validate_parameters(
    parameters: Mapping[str, Any],
    arguments: Mapping[str, Any],
) -> Optional[str]:
    validator_class = _validator_for(parameters)
    if validator_class is None:
        return unusable_tool_schema_error()
    # Empty registry: local $id / $ref resolve from this document; remote
    # retrieval is disabled so MCP schemas cannot trigger outbound fetches.
    validator = validator_class(parameters, registry=Registry())
    validator.check_schema(parameters)
    validation_errors = sorted(
        validator.iter_errors(dict(arguments)),
        key=_validation_error_sort_key,
    )
    if not validation_errors:
        return None

    messages = _unique_validation_messages(validation_errors)
    return format_retryable_error_as_json(
        f"Invalid tool arguments: {' '.join(messages)}",
        code=INVALID_ARGUMENTS_ERROR_CODE,
    )


def _validator_for(parameters: Mapping[str, Any]) -> Any:
    """Select an MCP-supported JSON Schema dialect."""
    dialect = parameters.get("$schema")
    if dialect is None:
        return Draft202012Validator
    if not isinstance(dialect, str):
        return None

    normalized_dialect = dialect.rstrip("#")
    if normalized_dialect == "http://json-schema.org/draft-07/schema":
        return Draft7Validator
    if normalized_dialect == "https://json-schema.org/draft/2020-12/schema":
        return Draft202012Validator
    return None


def _validation_error_sort_key(error: ValidationError) -> tuple[str, str]:
    """Return a deterministic order without including argument values."""
    return ".".join(str(part) for part in error.absolute_path), str(error.validator)


def _unique_validation_messages(errors: list[ValidationError]) -> list[str]:
    """Collapse jsonschema errors into one sentence per constraint kind."""
    missing: set[str] = set()
    unexpected: set[str] = set()
    other: list[str] = []
    for error in errors:
        if error.validator == "required":
            missing.update(_missing_required_names(error))
            continue
        if error.validator == "additionalProperties":
            if error.validator_value is not False:
                other.append(_format_constraint_error(error))
                continue
            unexpected.update(_unexpected_argument_names(error))
            continue
        other.append(_format_constraint_error(error))

    messages: list[str] = []
    if missing:
        messages.append(f"Missing required argument(s): {_format_names(missing)}.")
    if unexpected:
        messages.append(f"Unexpected argument(s): {_format_names(unexpected)}.")
    messages.extend(other)
    return messages


def _missing_required_names(error: ValidationError) -> set[str]:
    required = error.validator_value
    if not isinstance(required, list):
        return set()
    present = set(error.instance) if isinstance(error.instance, Mapping) else set()
    return {_qualified_name(error, name) for name in required if name not in present}


def _unexpected_argument_names(error: ValidationError) -> set[str]:
    """Names rejected by ``additionalProperties``, excluding ``patternProperties``."""
    instance = error.instance
    schema = error.schema
    if not isinstance(instance, Mapping) or not isinstance(schema, Mapping):
        return set()

    properties = schema.get("properties", {})
    allowed = set(properties) if isinstance(properties, Mapping) else set()
    pattern_properties = schema.get("patternProperties", {})
    patterns = (
        [str(pattern) for pattern in pattern_properties]
        if isinstance(pattern_properties, Mapping)
        else []
    )
    unexpected: set[str] = set()
    for key in instance:
        name = str(key)
        if name in allowed or _matches_pattern_property(name, patterns):
            continue
        unexpected.add(_qualified_name(error, name))
    return unexpected


def _qualified_name(error: ValidationError, name: Any) -> str:
    path = [str(part) for part in error.absolute_path]
    return ".".join([*path, str(name)])


def _matches_pattern_property(name: str, patterns: list[str]) -> bool:
    for pattern in patterns:
        try:
            if re.search(pattern, name) is not None:
                return True
        except re.error:
            continue
    return False


def _format_constraint_error(error: ValidationError) -> str:
    """Format a non-required, non-additionalProperties schema constraint."""
    path = ".".join(str(part) for part in error.absolute_path)
    subject = f"Argument '{path}'" if path else "Arguments"
    if error.validator == "type":
        return f"{subject} must match type {_format_expected_types(error)}."
    return f"{subject} must satisfy the '{error.validator}' schema constraint."


def _format_names(names: set[Any]) -> str:
    """Format schema property names in a stable order."""
    return ", ".join(f"'{name}'" for name in sorted(str(name) for name in names))


def _format_expected_types(error: ValidationError) -> str:
    """Format one or more JSON-schema types."""
    expected = error.validator_value
    if isinstance(expected, list):
        return " or ".join(f"'{type_name}'" for type_name in expected)
    return f"'{expected}'"
